CREATE OR REPLACE FUNCTION public.tc_admin_grant_oracle_draws(p_operation_id uuid, p_cliente_id uuid, p_actor_user_id uuid, p_amount numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor public.workers%rowtype;
  movement public.cliente_oracle_credit_movements%rowtype;
  grant_reference text := 'admin:oracle:tiradas:' || p_operation_id::text;
  clean_reason text := btrim(coalesce(p_reason, ''));
  balance_before integer;
  balance_after integer;
  receipt jsonb;
begin
  if p_operation_id is null or p_cliente_id is null or p_actor_user_id is null then
    raise exception 'INVALID_ADJUSTMENT';
  end if;
  if p_amount is null or p_amount <> trunc(p_amount) or p_amount not between 1 and 100 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if char_length(clean_reason) not between 3 and 500 then raise exception 'INVALID_REASON'; end if;

  select * into actor from public.workers
    where user_id = p_actor_user_id and role = 'admin' and is_active is distinct from false for share;
  if not found then raise exception 'FORBIDDEN'; end if;

  perform pg_advisory_xact_lock(hashtextextended(grant_reference, 0));
  select * into movement from public.cliente_oracle_credit_movements where reference = grant_reference;
  if found then
    if movement.cliente_id <> p_cliente_id or movement.amount <> p_amount
      or movement.movement_type <> 'adjustment' or movement.notes is distinct from clean_reason
      or movement.meta->>'source' is distinct from 'admin_client_balances'
      or movement.meta->>'actor_user_id' is distinct from p_actor_user_id::text
      or movement.meta->>'actor_worker_id' is distinct from actor.id::text then
      raise exception 'OPERATION_CONFLICT';
    end if;
    return movement.meta || jsonb_build_object('movement_id',movement.id,'created_at',movement.created_at,'replayed',true);
  end if;

  -- Same per-customer lock as consume_cliente_oracle_credit. The parent-row
  -- FOR UPDATE also serializes inserts from purchase grants via their client FK.
  perform pg_advisory_xact_lock(hashtext(p_cliente_id::text));
  perform 1 from public.crm_clientes where id = p_cliente_id for update;
  if not found then raise exception 'CLIENT_NOT_FOUND'; end if;
  balance_before := public.get_cliente_oracle_balance(p_cliente_id);
  if balance_before::bigint + p_amount > 2147483647 then raise exception 'ORACLE_BALANCE_LIMIT'; end if;
  balance_after := balance_before + p_amount::integer;
  receipt := jsonb_build_object(
    'source','admin_client_balances','operation_id',p_operation_id,'cliente_id',p_cliente_id,
    'actor_user_id',p_actor_user_id,'actor_worker_id',actor.id,
    'actor_name',coalesce(nullif(btrim(actor.display_name),''),'Administración'),
    'reason',clean_reason,'amount',p_amount::integer,
    'before_balance',balance_before,'after_balance',balance_after
  );
  insert into public.cliente_oracle_credit_movements
    (cliente_id,amount,movement_type,reference,notes,meta,created_at)
  values (p_cliente_id,p_amount::integer,'adjustment',grant_reference,clean_reason,receipt,clock_timestamp())
  returning * into movement;
  if public.get_cliente_oracle_balance(p_cliente_id) is distinct from balance_after then
    raise exception 'ORACLE_GRANT_CONTRACT_MISMATCH';
  end if;
  return receipt || jsonb_build_object('movement_id',movement.id,'created_at',movement.created_at,'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_admin_adjust_spins(p_operation_id uuid, p_cliente_id uuid, p_actor_user_id uuid, p_level integer, p_delta integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare prior public.tc_admin_spin_adjustments; ids uuid[]; n integer; actor text;
begin
 if p_operation_id is null or p_cliente_id is null or p_actor_user_id is null or p_level is null or p_level not between 1 and 5 or p_delta is null or p_delta=0 or abs(p_delta::bigint)>100 or length(trim(coalesce(p_reason,''))) not between 3 and 500 then raise exception 'INVALID_ADJUSTMENT'; end if;
 select coalesce(display_name,email,'Admin') into actor from public.workers where user_id=p_actor_user_id and role='admin' and is_active is distinct from false;
 if not found then raise exception 'FORBIDDEN'; end if;
 perform pg_advisory_xact_lock(hashtext('admin-spin:'||p_operation_id::text));
 select * into prior from public.tc_admin_spin_adjustments where operation_id=p_operation_id;
 if found then
  if prior.cliente_id<>p_cliente_id or prior.actor_user_id<>p_actor_user_id or prior.nivel<>p_level or prior.delta<>p_delta or prior.reason<>trim(p_reason) then raise exception 'OPERATION_CONFLICT'; end if;
  return to_jsonb(prior)||jsonb_build_object('replayed',true);
 end if;
 -- Same locking order as cliente_girar_ruleta_ultra_v1: client, then spin.
 perform 1 from public.crm_clientes where id=p_cliente_id for update;
 if not found then raise exception 'CLIENT_NOT_FOUND'; end if;
 select count(*) into n from public.cliente_ruleta_giros where cliente_id=p_cliente_id and nivel=p_level and estado='pending';
 if p_delta<0 and n < -p_delta then raise exception 'INSUFFICIENT_SPINS'; end if;
 if p_delta>0 then
  with added as (
   insert into public.cliente_ruleta_giros(cliente_id,payment_key,source,nivel,estado,required_rank)
   select p_cliente_id,'admin-adjustment:'||p_operation_id||':'||i,'admin_adjustment',p_level,'pending',case when p_level=5 then 'diamante' else null end from generate_series(1,p_delta) i returning id
  ) select array_agg(id) into ids from added;
 else
  select array_agg(id) into ids from (select id from public.cliente_ruleta_giros where cliente_id=p_cliente_id and nivel=p_level and estado='pending' order by created_at desc,id limit -p_delta for update) s;
  update public.cliente_ruleta_giros set estado='revoked' where id=any(ids) and estado='pending';
 end if;
 insert into public.tc_admin_spin_adjustments values(p_operation_id,p_cliente_id,p_actor_user_id,p_level,p_delta,trim(p_reason),n,n+p_delta,ids,now()) returning * into prior;
 insert into public.crm_client_notes(cliente_id,texto,author_user_id,author_name,event_type,event_data,is_pinned)
 values(p_cliente_id::text,format('Ajuste de giros · Nivel %s · %s → %s. %s',p_level,n,n+p_delta,trim(p_reason)),p_actor_user_id,actor,'admin_spin_adjustment',to_jsonb(prior),false);
 return to_jsonb(prior)||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.tc_atlas_execute_action(p_user uuid, p_proposal uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare actor public.workers; proposal public.atlas_admin_proposals; v_result jsonb; promo public.tc_client_promotions; detail jsonb; disabled jsonb;
begin
 select * into actor from public.workers where user_id=p_user and role='admin' and is_active is distinct from false;
 if not found then raise exception 'FORBIDDEN'; end if;
 select * into proposal from public.atlas_admin_proposals where id=p_proposal and worker_id=actor.id for update;
 if not found then raise exception 'PROPOSAL_NOT_FOUND'; end if;
 if proposal.status='completed' then return jsonb_build_object('result',proposal.result,'replayed',true); end if;
 if proposal.status<>'pending' or proposal.expires_at<=now() then raise exception 'PROPOSAL_UNAVAILABLE'; end if;
 detail:=proposal.payload;
 if proposal.kind='grant_spins' then
   v_result:=public.tc_admin_adjust_spins(proposal.id,(detail->>'client_id')::uuid,p_user,(detail->>'level')::integer,(detail->>'amount')::integer,detail->>'reason');
 elsif proposal.kind='grant_coins' then
   v_result:=public.admin_gift_client_coins((detail->>'client_id')::uuid,actor.id,(detail->>'amount')::integer,detail->>'reason',proposal.id);
 elsif proposal.kind in ('activate_promotion','deactivate_promotion') then
   perform pg_advisory_xact_lock(hashtext('atlas-promotions'));
   lock table public.tc_client_promotions,public.tc_client_promotion_packages in share row exclusive mode;
   select * into promo from public.tc_client_promotions where id=(detail->>'promotion_id')::uuid for update;
   if not found then raise exception 'PROMOTION_NOT_FOUND'; end if;
   if promo.promotion_kind is distinct from 'standard' then raise exception 'INVALID_PROMOTION_KIND'; end if;
   if promo.updated_at is distinct from (detail->>'updated_at')::timestamptz then raise exception 'PROMOTION_CHANGED'; end if;
   if proposal.kind='activate_promotion' then
     if coalesce((select jsonb_agg(id order by id) from public.tc_client_promotions where status='active' and promotion_kind='standard' and id<>promo.id),'[]') is distinct from detail->'previous_active' then raise exception 'PROMOTION_CHANGED'; end if;
     if (select count(*) from public.tc_client_promotion_packages where promotion_id=promo.id and is_active)<>jsonb_array_length(detail->'package_versions') or exists(select 1 from public.tc_client_promotion_packages p where p.promotion_id=promo.id and p.is_active and not exists(select 1 from jsonb_array_elements(detail->'package_versions') v where (v->>'id')::uuid=p.id and (v->>'updated_at')::timestamptz is not distinct from p.updated_at)) then raise exception 'PROMOTION_CHANGED'; end if;
     if promo.status='archived' or (not coalesce(promo.active_until_disabled,false) and promo.ends_at<=now()) then raise exception 'PROMOTION_EXPIRED'; end if;
     if not exists(select 1 from public.tc_client_promotion_packages where promotion_id=promo.id and is_active=true and price>0) then raise exception 'PROMOTION_WITHOUT_PACKAGES'; end if;
     select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') into disabled from public.tc_client_promotions where status='active' and promotion_kind='standard' and id<>promo.id;
     update public.tc_client_promotions set status='inactive',deactivated_at=now(),updated_at=now() where status='active' and promotion_kind='standard' and id<>promo.id;
     update public.tc_client_promotions set status='active',activated_at=now(),activated_by=p_user,deactivated_at=null,starts_at=now(),updated_at=now() where id=promo.id returning * into promo;
   else
     update public.tc_client_promotions set status='inactive',deactivated_at=now(),updated_at=now() where id=promo.id returning * into promo;
   end if;
   v_result:=jsonb_build_object('promotion_id',promo.id,'name',promo.name,'status',promo.status,'deactivated_promotions',coalesce(disabled,'[]'));
   insert into public.tc_client_promotion_audit(promotion_id,action,actor_user_id,snapshot) values(promo.id,proposal.kind,p_user,v_result||jsonb_build_object('source','atlas','proposal_id',proposal.id));
 elsif proposal.kind='save_memory' then
   if length(btrim(coalesce(detail->>'content',''))) not between 1 and 2000 then raise exception 'INVALID_MEMORY'; end if;
   insert into public.atlas_admin_memories(worker_id,content) values(actor.id,btrim(detail->>'content')) returning jsonb_build_object('memory_id',id,'saved',true) into v_result;
 elsif proposal.kind='dispatch_contacts' or proposal.kind='create_task' then
   v_result:=public.tc_atlas_dispatch(p_user,detail,proposal.id);
 else raise exception 'UNKNOWN_ACTION'; end if;
 update public.atlas_admin_proposals set status='completed',result=v_result,executed_at=now(),updated_at=now() where id=proposal.id;
 insert into public.atlas_admin_audit(worker_id,operation_id,action,entity_type,entity_id,detail)
 values(actor.id,proposal.id,proposal.kind,'proposal',proposal.id::text,v_result);
 return jsonb_build_object('result',v_result,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.admin_gift_client_coins(p_client_id uuid, p_admin_worker_id uuid, p_amount integer, p_reason text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_balance integer;
  v_existing record;
  v_movement_id text;
  v_client_name text;
begin
  if p_client_id is null or p_admin_worker_id is null or p_operation_id is null then
    raise exception 'GIFT_REQUIRED_FIELDS';
  end if;
  if p_amount < 1 or p_amount > 1000000 then
    raise exception 'COIN_AMOUNT_INVALID';
  end if;
  if nullif(btrim(p_reason), '') is null or length(btrim(p_reason)) > 500 then
    raise exception 'COIN_REASON_INVALID';
  end if;
  if not exists (
    select 1 from public.workers w
    where w.id = p_admin_worker_id
      and w.role = 'admin'
      and coalesce(w.is_active, true) = true
  ) then
    raise exception 'ADMIN_NOT_ALLOWED';
  end if;

  -- Serializa reintentos simultáneos de la misma operación.
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text, 0));

  select h.id, h.saldo_despues, h.cliente_id, h.puntos
    into v_existing
  from public.cliente_puntos_historial h
  where h.operation_id = p_operation_id;

  if found then
    if v_existing.cliente_id <> p_client_id or v_existing.puntos <> p_amount then
      raise exception 'OPERATION_ID_CONFLICT';
    end if;
    return jsonb_build_object(
      'duplicated', true,
      'movement_id', v_existing.id,
      'balance', coalesce(v_existing.saldo_despues, 0)
    );
  end if;

  update public.crm_clientes c
  set puntos = coalesce(c.puntos, 0) + p_amount,
      updated_at = now()
  where c.id = p_client_id
  returning coalesce(c.puntos, 0), concat_ws(' ', c.nombre, c.apellido)
    into v_balance, v_client_name;

  if not found then
    raise exception 'CLIENT_NOT_FOUND';
  end if;

  insert into public.cliente_puntos_historial (
    cliente_id, tipo, puntos, descripcion, operation_id,
    admin_worker_id, saldo_despues, meta, created_at
  ) values (
    p_client_id,
    'regalo_admin',
    p_amount,
    'Regalo de administración: ' || btrim(p_reason),
    p_operation_id,
    p_admin_worker_id,
    v_balance,
    jsonb_build_object('source', 'admin_client_web', 'reason', btrim(p_reason)),
    now()
  ) returning id::text into v_movement_id;

  insert into public.cliente_notificaciones (
    cliente_id, tipo, titulo, mensaje, leida, meta, created_at
  ) values (
    p_client_id,
    'coin_gift',
    '¡Tienes un obsequio!',
    'Has recibido +' || p_amount || ' Coins. ' || btrim(p_reason) ||
      ' Nuevo saldo: ' || v_balance || ' Coins.',
    false,
    jsonb_build_object(
      'operation_id', p_operation_id,
      'amount', p_amount,
      'balance', v_balance,
      'reason', btrim(p_reason),
      'admin_worker_id', p_admin_worker_id
    ),
    now()
  );

  return jsonb_build_object(
    'duplicated', false,
    'movement_id', v_movement_id,
    'client_name', nullif(btrim(v_client_name), ''),
    'amount', p_amount,
    'balance', v_balance
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_rendimiento_update_v2(p_worker uuid, p_id uuid, p_revision bigint, p_tiempo numeric, p_importe numeric, p_tarotista_nombre text, p_blocks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.rendimiento_llamadas; updated public.rendimiento_llamadas;
 reason text; b jsonb; blocks jsonb; summary text; before_data jsonb; n integer; tarotista_name text;
BEGIN
 SELECT * INTO r FROM public.rendimiento_llamadas WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'El registro ya no existe.' USING ERRCODE='P0002'; END IF;
 -- Serializa la corrección frente a cambios de estado de facturas existentes.
 PERFORM i.id FROM public.invoices i WHERE i.month_key=to_char(r.fecha_hora AT TIME ZONE 'UTC','YYYY-MM')
 ORDER BY i.id FOR SHARE;
 reason:=public.tc_rendimiento_edit_reason(r,p_worker);
 IF reason IS NOT NULL THEN RAISE EXCEPTION '%',reason USING ERRCODE='42501'; END IF;
 IF p_revision IS NULL OR p_revision<>r.edit_revision THEN
 RAISE EXCEPTION 'El registro cambió desde que lo abriste. Cancela y actualiza antes de editar de nuevo.' USING ERRCODE='40001'; END IF;
 IF p_tiempo IS NULL OR p_importe IS NULL OR p_tiempo<0 OR p_importe<0
 OR p_tiempo>1000000 OR p_importe>1000000 OR round(p_tiempo,2)<>p_tiempo OR round(p_importe,2)<>p_importe
 OR p_tiempo::text='NaN' OR p_importe::text='NaN' THEN RAISE EXCEPTION 'Cifras inválidas.' USING ERRCODE='22023'; END IF;
 tarotista_name:=regexp_replace(btrim(coalesce(p_tarotista_nombre,'')),'[[:space:]]+',' ','g');
 IF tarotista_name='' OR char_length(tarotista_name)>120 THEN RAISE EXCEPTION 'Nombre de tarotista inválido.' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_blocks) IS DISTINCT FROM 'array' OR jsonb_array_length(p_blocks)>32 THEN
 RAISE EXCEPTION 'Distribución inválida.' USING ERRCODE='22023'; END IF;
 FOR b IN SELECT value FROM jsonb_array_elements(p_blocks) LOOP
   IF coalesce(b->>'code','') NOT IN ('FREE','RUEDA','CLIENTE','REPITE','CALL','OTROS')
   OR coalesce(b->>'minutes','') !~ '^[0-9]+(\.[0-9]{1,2})?$'
   THEN RAISE EXCEPTION 'Código o minutos inválidos.' USING ERRCODE='22023'; END IF;
   IF (b->>'minutes')::numeric<=0 OR (b->>'minutes')::numeric>1000000 THEN
   RAISE EXCEPTION 'Los minutos del tramo deben ser positivos.' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF (SELECT coalesce(sum((value->>'minutes')::numeric),0) FROM jsonb_array_elements(p_blocks))<>p_tiempo
 THEN RAISE EXCEPTION 'Los tramos deben sumar exactamente el tiempo total.' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',code,'minutes',minutes) ORDER BY pos),'[]'::jsonb),
 coalesce(string_agg(trim_scale(minutes)::text||' '||lower(code),' · ' ORDER BY pos),'')
 INTO blocks,summary FROM (
 SELECT value->>'code' code,sum((value->>'minutes')::numeric) minutes,
 array_position(ARRAY['FREE','RUEDA','CLIENTE','REPITE','CALL','OTROS'],value->>'code') pos
 FROM jsonb_array_elements(p_blocks) GROUP BY value->>'code') s;
 n:=jsonb_array_length(blocks);
 before_data:=jsonb_build_object('tiempo',r.tiempo,'importe',r.importe,'resumen_codigo',r.resumen_codigo,
 'tarotista_nombre',r.tarotista_nombre,'codigo_1',r.codigo_1,'minutos_1',r.minutos_1,'codigo_2',r.codigo_2,'minutos_2',r.minutos_2,'code_blocks',r.code_blocks,'revision',r.edit_revision);
 -- No incluir importe en el UPDATE si no cambia: evita disparar lógica de compra ajena a los códigos.
 UPDATE public.rendimiento_llamadas SET tiempo=p_tiempo,tarotista_nombre=tarotista_name,code_blocks=blocks,resumen_codigo=summary,
 codigo_1=CASE WHEN n<=2 THEN blocks->0->>'code' ELSE NULL END,
 minutos_1=CASE WHEN n<=2 THEN coalesce((blocks->0->>'minutes')::numeric,0) ELSE 0 END,
 codigo_2=CASE WHEN n<=2 THEN blocks->1->>'code' ELSE NULL END,
 minutos_2=CASE WHEN n<=2 THEN coalesce((blocks->1->>'minutes')::numeric,0) ELSE 0 END WHERE id=p_id;
 IF r.importe IS DISTINCT FROM p_importe THEN UPDATE public.rendimiento_llamadas SET importe=p_importe WHERE id=p_id; END IF;
 SELECT * INTO updated FROM public.rendimiento_llamadas WHERE id=p_id;
 INSERT INTO public.crm_audit_logs(worker_id,action_type,entity_type,entity_id,payload)
 VALUES(p_worker,'rendimiento_update','rendimiento_llamadas',p_id,jsonb_build_object('before',before_data,
 'after',jsonb_build_object('tarotista_nombre',updated.tarotista_nombre,'tiempo',updated.tiempo,'importe',updated.importe,'code_blocks',updated.code_blocks,
 'resumen_codigo',updated.resumen_codigo,'revision',updated.edit_revision)));
 RETURN to_jsonb(updated)||jsonb_build_object('can_edit',true,'can_delete',
 (SELECT role::text='admin' OR updated.telefonista_worker_id=p_worker::text FROM public.workers WHERE id=p_worker),'edit_reason',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.tc_captacion_whatsapp_claim(p_delivery_id uuid, p_request_id uuid, p_lead_id uuid, p_worker_id uuid, p_auth_user_id uuid, p_submission_key text, p_content_sid text, p_from_number text, p_to_number text, p_callback_token uuid, p_expected_cliente_id uuid, p_client_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lead public.captacion_leads%rowtype;
  v_worker public.workers%rowtype;
  v_client public.crm_clientes%rowtype;
  v_delivery public.captacion_whatsapp_deliveries%rowtype;
  v_origin text;
  v_event_key text;
  v_submitted_at timestamptz;
begin
  -- Serialize different central users and tabs acting on the same customer lead.
  select * into v_lead from public.captacion_leads where id = p_lead_id for update;
  if not found then raise exception 'LEAD_NOT_FOUND'; end if;
  select * into v_worker from public.workers where id = p_worker_id and is_active = true
    and role in ('admin','central') and (user_id = p_auth_user_id or auth_user_id = p_auth_user_id);
  if not found then raise exception 'FORBIDDEN'; end if;
  if v_worker.role <> 'admin' and v_lead.assigned_worker_id is not null and v_lead.assigned_worker_id <> p_worker_id then raise exception 'FORBIDDEN'; end if;
  -- Provider preflight can take seconds. Recheck the exact CRM snapshot while
  -- locking both the lead and client before reserving any outbound message.
  if v_lead.cliente_id is distinct from p_expected_cliente_id then raise exception 'CLIENT_CHANGED'; end if;
  select * into v_client from public.crm_clientes where id = v_lead.cliente_id for share;
  if not found then raise exception 'LEAD_NOT_FOUND'; end if;
  if p_client_snapshot is distinct from jsonb_build_object(
    'telefono_normalizado',v_client.telefono_normalizado,'telefono',v_client.telefono,
    'pais',v_client.pais,'nombre',v_client.nombre,'apellido',v_client.apellido
  ) then raise exception 'CLIENT_CHANGED'; end if;
  v_origin := coalesce(nullif(v_client.origen,''),v_lead.origen,'');
  if lower(v_origin) like '%orion%' then raise exception 'LEAD_NOT_FOUND'; end if;
  select * into v_delivery from public.captacion_whatsapp_deliveries where request_id = p_request_id;
  if found then
    if v_delivery.lead_id <> p_lead_id then raise exception 'REQUEST_CONFLICT'; end if;
    return jsonb_build_object('claimed',false,'delivery',to_jsonb(v_delivery));
  end if;
  select 'meta:' || leadgen_id, meta_created_at into v_event_key, v_submitted_at
    from public.meta_lead_events where captacion_lead_id = p_lead_id and status = 'processed' and meta_created_at <= now()
    order by meta_created_at desc, leadgen_id desc limit 1;
  v_event_key := coalesce(v_event_key,'initial');
  if p_submission_key is distinct from v_event_key then raise exception 'SUBMISSION_CHANGED'; end if;
  select * into v_delivery from public.captacion_whatsapp_deliveries where lead_id = p_lead_id and submission_key = p_submission_key;
  if found then return jsonb_build_object('claimed',false,'delivery',to_jsonb(v_delivery)); end if;
  if v_lead.closed_at is not null and (v_submitted_at is null or v_lead.closed_at >= v_submitted_at) then raise exception 'LEAD_CLOSED'; end if;
  if p_content_sid !~ '^HX[0-9a-fA-F]{32}$' or p_from_number !~ '^whatsapp:\+[1-9][0-9]{7,14}$' or p_to_number !~ '^whatsapp:\+[1-9][0-9]{7,14}$' then raise exception 'INVALID_MESSAGE'; end if;
  insert into public.captacion_whatsapp_deliveries (id,lead_id,cliente_id,submission_key,request_id,worker_id,auth_user_id,content_sid,from_number,to_number,callback_token)
    values (p_delivery_id,p_lead_id,v_lead.cliente_id,p_submission_key,p_request_id,p_worker_id,p_auth_user_id,p_content_sid,p_from_number,p_to_number,p_callback_token)
    returning * into v_delivery;
  insert into public.captacion_whatsapp_delivery_events (delivery_id,status,source) values (v_delivery.id,'sending','claim');
  return jsonb_build_object('claimed',true,'delivery',to_jsonb(v_delivery));
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_rendimiento_update(p_worker uuid, p_id uuid, p_revision bigint, p_tiempo numeric, p_importe numeric, p_blocks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.rendimiento_llamadas; updated public.rendimiento_llamadas;
 reason text; b jsonb; blocks jsonb; summary text; before_data jsonb; n integer;
BEGIN
 SELECT * INTO r FROM public.rendimiento_llamadas WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'El registro ya no existe.' USING ERRCODE='P0002'; END IF;
 -- Serializa la corrección frente a cambios de estado de facturas existentes.
 PERFORM i.id FROM public.invoices i WHERE i.month_key=to_char(r.fecha_hora AT TIME ZONE 'UTC','YYYY-MM')
 ORDER BY i.id FOR SHARE;
 reason:=public.tc_rendimiento_edit_reason(r,p_worker);
 IF reason IS NOT NULL THEN RAISE EXCEPTION '%',reason USING ERRCODE='42501'; END IF;
 IF p_revision IS NULL OR p_revision<>r.edit_revision THEN
 RAISE EXCEPTION 'El registro cambió desde que lo abriste. Cancela y actualiza antes de editar de nuevo.' USING ERRCODE='40001'; END IF;
 IF p_tiempo IS NULL OR p_importe IS NULL OR p_tiempo<0 OR p_importe<0
 OR p_tiempo>1000000 OR p_importe>1000000 OR round(p_tiempo,2)<>p_tiempo OR round(p_importe,2)<>p_importe
 OR p_tiempo::text='NaN' OR p_importe::text='NaN' THEN RAISE EXCEPTION 'Cifras inválidas.' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_blocks) IS DISTINCT FROM 'array' OR jsonb_array_length(p_blocks)>32 THEN
 RAISE EXCEPTION 'Distribución inválida.' USING ERRCODE='22023'; END IF;
 FOR b IN SELECT value FROM jsonb_array_elements(p_blocks) LOOP
   IF coalesce(b->>'code','') NOT IN ('FREE','RUEDA','CLIENTE','REPITE','CALL','OTROS')
   OR coalesce(b->>'minutes','') !~ '^[0-9]+(\.[0-9]{1,2})?$'
   THEN RAISE EXCEPTION 'Código o minutos inválidos.' USING ERRCODE='22023'; END IF;
   IF (b->>'minutes')::numeric<=0 OR (b->>'minutes')::numeric>1000000 THEN
   RAISE EXCEPTION 'Los minutos del tramo deben ser positivos.' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF (SELECT coalesce(sum((value->>'minutes')::numeric),0) FROM jsonb_array_elements(p_blocks))<>p_tiempo
 THEN RAISE EXCEPTION 'Los tramos deben sumar exactamente el tiempo total.' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',code,'minutes',minutes) ORDER BY pos),'[]'::jsonb),
 coalesce(string_agg(trim_scale(minutes)::text||' '||lower(code),' · ' ORDER BY pos),'')
 INTO blocks,summary FROM (
 SELECT value->>'code' code,sum((value->>'minutes')::numeric) minutes,
 array_position(ARRAY['FREE','RUEDA','CLIENTE','REPITE','CALL','OTROS'],value->>'code') pos
 FROM jsonb_array_elements(p_blocks) GROUP BY value->>'code') s;
 n:=jsonb_array_length(blocks);
 before_data:=jsonb_build_object('tiempo',r.tiempo,'importe',r.importe,'resumen_codigo',r.resumen_codigo,
 'codigo_1',r.codigo_1,'minutos_1',r.minutos_1,'codigo_2',r.codigo_2,'minutos_2',r.minutos_2,'code_blocks',r.code_blocks,'revision',r.edit_revision);
 -- No incluir importe en el UPDATE si no cambia: evita disparar lógica de compra ajena a los códigos.
 UPDATE public.rendimiento_llamadas SET tiempo=p_tiempo,code_blocks=blocks,resumen_codigo=summary,
 codigo_1=CASE WHEN n<=2 THEN blocks->0->>'code' ELSE NULL END,
 minutos_1=CASE WHEN n<=2 THEN (blocks->0->>'minutes')::numeric ELSE NULL END,
 codigo_2=CASE WHEN n<=2 THEN blocks->1->>'code' ELSE NULL END,
 minutos_2=CASE WHEN n<=2 THEN (blocks->1->>'minutes')::numeric ELSE NULL END WHERE id=p_id;
 IF r.importe IS DISTINCT FROM p_importe THEN UPDATE public.rendimiento_llamadas SET importe=p_importe WHERE id=p_id; END IF;
 SELECT * INTO updated FROM public.rendimiento_llamadas WHERE id=p_id;
 INSERT INTO public.crm_audit_logs(worker_id,action_type,entity_type,entity_id,payload)
 VALUES(p_worker,'rendimiento_update','rendimiento_llamadas',p_id,jsonb_build_object('before',before_data,
 'after',jsonb_build_object('tiempo',updated.tiempo,'importe',updated.importe,'code_blocks',updated.code_blocks,
 'resumen_codigo',updated.resumen_codigo,'revision',updated.edit_revision)));
 RETURN to_jsonb(updated)||jsonb_build_object('can_edit',true,'can_delete',
 (SELECT role::text='admin' OR updated.telefonista_worker_id=p_worker::text FROM public.workers WHERE id=p_worker),'edit_reason',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.tc_captacion_whatsapp_qr_claim(p_delivery_id uuid, p_request_id uuid, p_lead_id uuid, p_worker_id uuid, p_auth_user_id uuid, p_submission_key text, p_from_number text, p_to_number text, p_callback_token uuid, p_expected_cliente_id uuid, p_client_snapshot jsonb, p_gateway_session_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lead public.captacion_leads%rowtype;
  v_worker public.workers%rowtype;
  v_client public.crm_clientes%rowtype;
  v_delivery public.captacion_whatsapp_deliveries%rowtype;
  v_origin text;
  v_event_key text;
  v_submitted_at timestamptz;
begin
  -- Serialize different central users and tabs acting on the same customer lead.
  select * into v_lead from public.captacion_leads where id = p_lead_id for update;
  if not found then raise exception 'LEAD_NOT_FOUND'; end if;
  select * into v_worker from public.workers where id = p_worker_id and is_active = true
    and role in ('admin','central') and (user_id = p_auth_user_id or auth_user_id = p_auth_user_id);
  if not found then raise exception 'FORBIDDEN'; end if;
  if v_worker.role <> 'admin' and v_lead.assigned_worker_id is not null and v_lead.assigned_worker_id <> p_worker_id then raise exception 'FORBIDDEN'; end if;
  -- Provider preflight can take seconds. Recheck the exact CRM snapshot while
  -- locking both the lead and client before reserving any outbound message.
  if v_lead.cliente_id is distinct from p_expected_cliente_id then raise exception 'CLIENT_CHANGED'; end if;
  select * into v_client from public.crm_clientes where id = v_lead.cliente_id for share;
  if not found then raise exception 'LEAD_NOT_FOUND'; end if;
  if p_client_snapshot is distinct from jsonb_build_object(
    'telefono_normalizado',v_client.telefono_normalizado,'telefono',v_client.telefono,
    'pais',v_client.pais,'nombre',v_client.nombre,'apellido',v_client.apellido
  ) then raise exception 'CLIENT_CHANGED'; end if;
  v_origin := coalesce(nullif(v_client.origen,''),v_lead.origen,'');
  if lower(v_origin) like '%orion%' then raise exception 'LEAD_NOT_FOUND'; end if;
  select * into v_delivery from public.captacion_whatsapp_deliveries where request_id = p_request_id;
  if found then
    if v_delivery.lead_id <> p_lead_id then raise exception 'REQUEST_CONFLICT'; end if;
    return jsonb_build_object('claimed',false,'delivery',to_jsonb(v_delivery));
  end if;
  select 'meta:' || leadgen_id, meta_created_at into v_event_key, v_submitted_at
    from public.meta_lead_events where captacion_lead_id = p_lead_id and status = 'processed' and meta_created_at <= now()
    order by meta_created_at desc, leadgen_id desc limit 1;
  v_event_key := coalesce(v_event_key,'initial');
  if p_submission_key is distinct from v_event_key then raise exception 'SUBMISSION_CHANGED'; end if;
  select * into v_delivery from public.captacion_whatsapp_deliveries where lead_id = p_lead_id and submission_key = p_submission_key;
  if found then return jsonb_build_object('claimed',false,'delivery',to_jsonb(v_delivery)); end if;
  if v_lead.closed_at is not null and (v_submitted_at is null or v_lead.closed_at >= v_submitted_at) then raise exception 'LEAD_CLOSED'; end if;
  if p_gateway_session_id is null or p_gateway_session_id !~ '^[A-Za-z0-9_-]{1,64}$' or p_from_number !~ '^whatsapp:\+[1-9][0-9]{7,14}$' or p_to_number !~ '^whatsapp:\+[1-9][0-9]{7,14}$' then raise exception 'INVALID_MESSAGE'; end if;
  insert into public.captacion_whatsapp_deliveries (id,lead_id,cliente_id,submission_key,request_id,worker_id,auth_user_id,content_sid,from_number,to_number,callback_token,provider,gateway_session_id)
    values (p_delivery_id,p_lead_id,v_lead.cliente_id,p_submission_key,p_request_id,p_worker_id,p_auth_user_id,'qr:captacion-beneficios-v1',p_from_number,p_to_number,p_callback_token,'qr',p_gateway_session_id)
    returning * into v_delivery;
  insert into public.captacion_whatsapp_delivery_events (delivery_id,status,source) values (v_delivery.id,'sending','claim');
  return jsonb_build_object('claimed',true,'delivery',to_jsonb(v_delivery));
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_raffle_action(p_raffle uuid, p_worker uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.raffles; w public.workers; p public.raffle_prizes; e public.raffle_entries;
 v_revision bigint; v_entry uuid; v_pool jsonb; v_payload jsonb; v_action text; v_name text; v_position integer;
begin
 select * into w from public.workers where id=p_worker and role in ('central','admin') and is_active is not false;
 if not found then raise exception 'Sin permiso' using errcode='42501'; end if;
 if p_action='rule' and w.role<>'admin' then
   raise exception 'Solo un administrador puede realizar esta acción' using errcode='42501'; end if;
 if p_action not in ('save','draw','manual','confirm','cancel','rule') then raise exception 'Acción inválida'; end if;
 select * into r from public.raffles where id=p_raffle for update;
 if not found or r.status<>'active' then raise exception 'El sorteo ya no está activo'; end if;
 if p_action='rule' then
   if jsonb_typeof(p_data->'allow_repeat_winners') is distinct from 'boolean' then raise exception 'Regla inválida'; end if;
   if exists(select 1 from public.raffle_prizes where raffle_id=r.id and selected_at is not null and confirmed_at is null) then
     raise exception 'Hay un ganador pendiente de confirmar o descartar.'; end if;
   update public.raffles set allow_repeat_winners=(p_data->>'allow_repeat_winners')::boolean,updated_at=now() where id=r.id;
   v_payload=jsonb_build_object('previous',r.allow_repeat_winners,'allow_repeat_winners',p_data->'allow_repeat_winners');
   v_action='raffle_rule_changed';
 elsif p_action='save' then
   v_position=(p_data->>'position')::integer; v_name=btrim(p_data->>'name');
   if v_position is null or v_position not between 1 and 100 or v_name is null or char_length(v_name) not between 1 and 200 then raise exception 'Nombre o posición inválidos'; end if;
   select * into p from public.raffle_prizes where raffle_id=r.id and position=v_position for update;
   if found then
     if p.selected_at is not null then raise exception 'No se puede cambiar un premio con un número seleccionado'; end if;
     if p.name is distinct from p_data->>'previous_name' then raise exception 'El premio cambió en otro panel. Revisa antes de guardar.'; end if;
     update public.raffle_prizes set name=v_name where id=p.id;
   else
     insert into public.raffle_prizes(raffle_id,position,name) values(r.id,v_position,v_name) returning * into p;
   end if;
   v_payload=jsonb_build_object('prize_id',p.id,'position',v_position,'name',v_name);
   v_action='raffle_prize_saved';
 else
   select * into p from public.raffle_prizes where id=(p_data->>'prize_id')::uuid and raffle_id=r.id for update;
   if not found then raise exception 'Premio no encontrado'; end if;
   v_revision=(p_data->>'revision')::bigint;
   if v_revision is null or v_revision<>p.selection_revision then raise exception 'La selección cambió en otro panel. Actualiza antes de continuar.'; end if;
   -- Idempotencia de confirmación: no publica ni audita dos veces.
   if p.confirmed_at is not null then
     if p_action='confirm' then return jsonb_build_object('ok',true,'already_confirmed',true); end if;
     raise exception 'El premio ya está confirmado; no puede volver a sortearse ni descartarse';
   end if;
   if p_action in ('draw','manual') then
     if p.selected_at is not null then
       raise exception 'Hay un ganador pendiente de confirmar o descartar.'; end if;
     if p_action='draw' then
       -- La API usa crypto.randomInt. Verificar exactamente la población utilizada.
       select coalesce(jsonb_agg(x.id order by x.raffle_number),'[]'::jsonb) into v_pool
       from public.raffle_entries x join public.crm_clientes c on c.id=x.client_id where x.raffle_id=r.id and
       (r.allow_repeat_winners or not exists(select 1 from public.raffle_prizes q where q.raffle_id=r.id and q.confirmed_at is not null and q.candidate_client_id=x.client_id));
       if v_pool is distinct from p_data->'pool_ids' then raise exception 'Los participantes cambiaron. Actualiza y vuelve a girar.'; end if;
     end if;
     v_entry=(p_data->>'entry_id')::uuid;
     select * into e from public.raffle_entries where id=v_entry and raffle_id=r.id for share;
     if not found then raise exception 'Participación no válida para este sorteo'; end if;
     if not r.allow_repeat_winners and exists(select 1 from public.raffle_prizes where raffle_id=r.id and confirmed_at is not null and candidate_client_id=e.client_id) then
       raise exception 'Este cliente ya ganó; todos sus números quedan excluidos'; end if;
     if p_action='manual' and (jsonb_typeof(p_data->'is_test') is distinct from 'boolean' or jsonb_typeof(p_data->'simulation_only') is distinct from 'boolean') then raise exception 'Indica si la selección manual es una prueba'; end if;
     update public.raffle_prizes set candidate_entry_id=e.id,candidate_number=e.raffle_number,candidate_client_id=e.client_id,
       selected_at=now(),selected_by=w.id,selection_method=case when p_action='draw' then 'roulette' else 'manual' end,
       is_test=p_action='manual' and (p_data->>'is_test')::boolean,
       simulation_only=p_action='manual' and (p_data->>'is_test')::boolean and (p_data->>'simulation_only')::boolean,
       selection_revision=selection_revision+1 where id=p.id returning * into p;
     v_action='raffle_selected';
   else
     if p.selected_at is null then raise exception 'No hay un ganador provisional'; end if;
     if p_action='confirm' then
       select * into e from public.raffle_entries where id=p.candidate_entry_id and raffle_id=r.id for share;
       if not found or e.client_id is distinct from p.candidate_client_id or e.raffle_number is distinct from p.candidate_number then
         raise exception 'La participación cambió; descarta y revisa el candidato'; end if;
       if not r.allow_repeat_winners and exists(select 1 from public.raffle_prizes where raffle_id=r.id and confirmed_at is not null and candidate_client_id=p.candidate_client_id) then
         raise exception 'Este cliente ya ganó; descarta la selección pendiente'; end if;
       if not p.simulation_only then
         update public.raffle_prizes set confirmed_at=now(),confirmed_by=w.id where id=p.id returning * into p;
         insert into public.raffle_public_winners(prize_id,raffle_id,position,prize_name,winning_number,confirmed_at,selection_method,is_test)
           values(p.id,r.id,p.position,p.name,p.candidate_number,p.confirmed_at,p.selection_method,p.is_test);
         v_action='raffle_confirmed';
       else v_action='raffle_simulated'; end if;
     else v_action='raffle_cancelled'; end if;
     if p_action='cancel' or p.simulation_only then
       update public.raffle_prizes set candidate_entry_id=null,candidate_number=null,candidate_client_id=null,selected_at=null,selected_by=null,
         selection_method='roulette',is_test=false,simulation_only=false,selection_revision=selection_revision+1 where id=p.id;
     end if;
   end if;
   select nullif(btrim(concat_ws(' ',nombre,apellido)),'') into v_name from public.crm_clientes where id=p.candidate_client_id;
   v_payload=jsonb_build_object('prize_id',p.id,'position',p.position,'prize_name',p.name,'entry_id',p.candidate_entry_id,
     'client_id',p.candidate_client_id,'number',p.candidate_number,'name',v_name,'method',p.selection_method,
     'is_test',p.is_test,'simulation_only',p.simulation_only,'selected_by',p.selected_by,'confirmed_by',p.confirmed_by,
     'selected_at',p.selected_at,'confirmed_at',p.confirmed_at,'revision',p.selection_revision);
 end if;
 -- Solo la API privada de administradores puede consultar este registro.
 insert into public.raffle_selection_audit(worker_id,action_type,entity_type,entity_id,payload)
 values(w.id,v_action,'raffle_selection',r.id,v_payload);
 return jsonb_build_object('ok',true);
end $function$

CREATE OR REPLACE FUNCTION public.tc_admin_adjust_coins(p_operation_id uuid, p_cliente_id uuid, p_actor_user_id uuid, p_amount numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  prior public.tc_admin_coin_adjustments%rowtype;
  actor public.workers%rowtype;
  movement public.cliente_puntos_historial%rowtype;
  gift jsonb;
  before_coins integer;
  after_coins integer;
  note_uuid uuid;
  audit_data jsonb;
  clean_reason text:=btrim(coalesce(p_reason,''));
begin
  if p_operation_id is null or p_cliente_id is null or p_actor_user_id is null then
    raise exception 'INVALID_ADJUSTMENT';
  end if;
  -- Numeric input prevents PostgreSQL from silently rounding a fractional JSON
  -- number to integer before validation at the RPC boundary.
  if p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity')
    or p_amount<>trunc(p_amount) or p_amount<1 or p_amount>1000000 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if char_length(clean_reason) not between 3 and 500 then
    raise exception 'INVALID_REASON';
  end if;

  -- The server passes its verified auth user, never an actor from the browser.
  -- Resolve/lock the current worker record so a stale or revoked role cannot
  -- authorize the transaction. Keep the existing null-is-active convention.
  select * into actor from public.workers
    where user_id=p_actor_user_id and role='admin' and is_active is distinct from false
    for share;
  if not found then raise exception 'FORBIDDEN'; end if;

  -- Same operation lock as admin_gift_client_coins. This also serializes callers
  -- using the existing admin-gift entry point, preventing cross-route retries.
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
  select * into prior from public.tc_admin_coin_adjustments where operation_id=p_operation_id;
  if found then
    if prior.cliente_id<>p_cliente_id or prior.actor_user_id<>p_actor_user_id
      or prior.actor_worker_id<>actor.id or prior.amount<>p_amount or prior.reason<>clean_reason then
      raise exception 'OPERATION_CONFLICT';
    end if;
    return to_jsonb(prior)||jsonb_build_object('replayed',true);
  end if;
  -- Never adopt another feature's receipt as a new manual adjustment.
  if exists(select 1 from public.cliente_puntos_historial where operation_id=p_operation_id) then
    raise exception 'OPERATION_CONFLICT';
  end if;

  select coalesce(puntos,0) into before_coins from public.crm_clientes
    where id=p_cliente_id for update;
  if not found then raise exception 'CLIENT_NOT_FOUND'; end if;
  if before_coins::bigint+p_amount>2147483647 then raise exception 'COIN_BALANCE_LIMIT'; end if;
  after_coins:=(before_coins::bigint+p_amount)::integer;

  gift:=public.admin_gift_client_coins(p_cliente_id,actor.id,p_amount::integer,clean_reason,p_operation_id);
  select * into movement from public.cliente_puntos_historial where operation_id=p_operation_id;
  if gift is null or coalesce((gift->>'duplicated')::boolean,false)
    or movement.id is null or movement.cliente_id is distinct from p_cliente_id
    or movement.admin_worker_id is distinct from actor.id or movement.puntos is distinct from p_amount::integer
    or movement.saldo_despues is distinct from after_coins
    or gift->>'movement_id' is distinct from movement.id::text
    or (select puntos from public.crm_clientes where id=p_cliente_id) is distinct from after_coins then
    raise exception 'COIN_GIFT_CONTRACT_MISMATCH';
  end if;

  audit_data:=jsonb_build_object(
    'operation_id',p_operation_id,'cliente_id',p_cliente_id,
    'actor_user_id',p_actor_user_id,'actor_worker_id',actor.id,
    'amount',p_amount::integer,'reason',clean_reason,
    'before_balance',before_coins,'after_balance',after_coins,
    'movement_id',movement.id,'source','admin_client_balances'
  );
  insert into public.crm_client_notes(cliente_id,texto,author_user_id,author_name,event_type,event_data,is_pinned)
  values(p_cliente_id::text,
    format('Coins añadidas manualmente por administración · +%s Coins · Saldo: %s → %s. Motivo: %s',p_amount::integer,before_coins,after_coins,clean_reason),
    p_actor_user_id,coalesce(nullif(btrim(actor.display_name),''),actor.email,'Admin'),
    'admin_coin_adjustment',audit_data,false)
  returning id into note_uuid;

  insert into public.tc_admin_coin_adjustments(
    operation_id,cliente_id,actor_user_id,actor_worker_id,amount,reason,
    before_balance,after_balance,movement_id,note_id
  ) values(
    p_operation_id,p_cliente_id,p_actor_user_id,actor.id,p_amount::integer,clean_reason,
    before_coins,after_coins,movement.id,note_uuid
  ) returning * into prior;

  -- The existing crm_clientes state trigger refreshes the shared client signal
  -- when puntos changes. No second signal write, purchase or spin is created.
  return to_jsonb(prior)||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.tc_admin_whatsapp_draft_get(p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_result jsonb;
begin
  perform 1 from public.workers w where w.user_id=p_actor_user_id and w.is_active is true and lower(w.role)='admin' for share;
  if not found then raise exception 'FORBIDDEN'; end if;
  select jsonb_build_object('version',d.version,'updated_at',d.updated_at,'slots',d.document->'slots') into v_result
  from public.tc_admin_whatsapp_drafts d where d.actor_user_id=p_actor_user_id;
  return coalesce(v_result, jsonb_build_object('version',0,'updated_at',null,'slots',jsonb_build_array(
    jsonb_build_object('slot',1,'label','WhatsApp 1','sender_phone','','message','','image_url','','contacts','[]'::jsonb),
    jsonb_build_object('slot',2,'label','WhatsApp 2','sender_phone','','message','','image_url','','contacts','[]'::jsonb))));
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_admin_whatsapp_draft_save(p_actor_user_id uuid, p_request_id uuid, p_expected_version bigint, p_document jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_document jsonb; v_request public.tc_admin_whatsapp_draft_requests%rowtype;
  v_version bigint := 0; v_updated_at timestamptz; v_result jsonb;
begin
  perform 1 from public.workers w where w.user_id=p_actor_user_id and w.is_active is true and lower(w.role)='admin' for share;
  if not found then raise exception 'FORBIDDEN'; end if;
  if p_request_id is null then raise exception 'INVALID_REQUEST_ID'; end if;
  if p_expected_version is null or p_expected_version < 0 or p_expected_version > 9007199254740990 then raise exception 'INVALID_VERSION'; end if;
  v_document := public.tc_admin_whatsapp_draft_normalize(p_document);
  -- Serializes first-save and existing-draft edits for this actor only.
  perform pg_advisory_xact_lock(hashtextextended('admin-whatsapp-draft:' || p_actor_user_id::text,0));
  select * into v_request from public.tc_admin_whatsapp_draft_requests r where r.actor_user_id=p_actor_user_id and r.request_id=p_request_id;
  if found then
    if v_request.expected_version <> p_expected_version or v_request.result_snapshot->'slots' <> v_document->'slots' then raise exception 'OPERATION_CONFLICT'; end if;
    return v_request.result_snapshot || jsonb_build_object('replayed',true);
  end if;
  select d.version into v_version from public.tc_admin_whatsapp_drafts d where d.actor_user_id=p_actor_user_id for update;
  v_version := coalesce(v_version,0);
  if v_version <> p_expected_version then raise exception 'VERSION_CONFLICT' using detail=jsonb_build_object('current_version',v_version)::text; end if;
  v_updated_at := clock_timestamp();
  v_result := jsonb_build_object('version',v_version+1,'updated_at',v_updated_at,'slots',v_document->'slots');
  insert into public.tc_admin_whatsapp_drafts(actor_user_id,version,document,updated_at) values(p_actor_user_id,v_version+1,v_document,v_updated_at)
  on conflict(actor_user_id) do update set version=excluded.version,document=excluded.document,updated_at=excluded.updated_at;
  insert into public.tc_admin_whatsapp_draft_requests(actor_user_id,request_id,expected_version,result_snapshot) values(p_actor_user_id,p_request_id,p_expected_version,v_result);
  return v_result || jsonb_build_object('replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.tc_admin_whatsapp_draft_resolve(p_actor_user_id uuid, p_phones text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_phones text[] := '{}'::text[]; v_phone text; v_result jsonb;
begin
  perform 1 from public.workers w where w.user_id=p_actor_user_id and w.is_active is true and lower(w.role)='admin' for share;
  if not found then raise exception 'FORBIDDEN'; end if;
  if p_phones is null or cardinality(p_phones)>600 then raise exception 'TOO_MANY_CONTACTS'; end if;
  foreach v_phone in array p_phones loop
    v_phone := public.tc_admin_whatsapp_draft_phone(v_phone);
    if not (v_phone=any(v_phones)) then v_phones := array_append(v_phones,v_phone); end if;
  end loop;
  -- Exact indexed comparisons only. No suffix matching, broad export, or country inference.
  -- CRM currently has no canonical WhatsApp blocklist/opt-out field. A web-login ban is not marketing consent.
  select coalesce(jsonb_agg(jsonb_build_object('phone',r.phone,'match',case when m.n=0 then 'none' when m.n=1 then 'unique' else 'ambiguous' end,
    'name',case when m.n=1 then m.name else '' end) order by r.ordinality),'[]'::jsonb) into v_result
  from unnest(v_phones) with ordinality r(phone,ordinality)
  cross join lateral (
    select count(*) n,min(c.name) name from (
      select left(btrim(concat_ws(' ',cl.nombre,nullif(btrim(cl.apellido),''))),160) name
      from public.crm_clientes cl where cl.telefono_normalizado=any(array[r.phone,substr(r.phone,2),'00'||substr(r.phone,2)]) limit 2
    ) c
  ) m;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.invoice_edit_atomic(p_invoice_id uuid, p_actor_id uuid, p_action text, p_line_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_inv public.invoices%rowtype; v_actor public.workers%rowtype; v_line public.invoice_lines%rowtype;
 v_id uuid; v_inc_id uuid; v_meta jsonb; v_amount numeric; v_kind text; v_label text; v_total numeric; v_date timestamptz; v_cancel boolean;
begin
 select * into v_actor from public.workers where id=p_actor_id and role='admin' and is_active is distinct from false;
 if not found then raise exception 'FORBIDDEN'; end if;
 select * into strict v_inv from public.invoices where id=p_invoice_id for update;
 if p_action='set_status' then
  if p_data->>'status' not in ('draft','pending','review','final','paid') then raise exception 'INVALID_STATUS'; end if;
  update public.invoices set status=p_data->>'status',updated_at=now() where id=p_invoice_id;
  return jsonb_build_object('ok',true);
 end if;
 if coalesce(v_inv.status,'') not in ('draft','pending','review') then raise exception 'La factura está cerrada. Vuelve a borrador para editarla.'; end if;
 if p_action='set_notes' then
  update public.invoices set notes=p_data->>'notes',updated_at=now() where id=p_invoice_id;
  return jsonb_build_object('ok',true);
 end if;
 if p_action not in ('add_line','update_line','delete_line') or p_line_id is null then raise exception 'INVALID_ACTION'; end if;
 select * into v_line from public.invoice_lines where id=p_line_id;
 if p_action='add_line' and found then
  if v_line.invoice_id<>p_invoice_id then raise exception 'INVALID_REQUEST'; end if;
  return jsonb_build_object('ok',true,'replayed',true,'total',v_inv.total);
 end if;
 if p_action<>'add_line' then
  if v_line.id is null or v_line.invoice_id<>p_invoice_id then raise exception 'LINE_NOT_FOUND'; end if;
  if v_line.kind='salary_base' or v_line.meta->>'locked'='true' or v_line.meta->>'protected'='true' then raise exception 'El sueldo fijo está protegido.'; end if;
 end if;
 v_cancel:=p_action='delete_line';
 v_kind:=coalesce(p_data->>'kind',v_line.kind,'adjustment');
 if v_line.kind='incident' then v_kind:='incident'; end if;
 v_label:=coalesce(nullif(trim(p_data->>'label'),''),v_line.label,'Ajuste');
 v_meta:=coalesce(v_line.meta,'{}')||coalesce(p_data->'meta','{}')||jsonb_build_object('source','manual_edit');
 if p_action='update_line' and (v_line.meta->>'source'='auto_generate' or v_line.meta->>'manual_override'='true') then v_meta:=v_meta||jsonb_build_object('manual_override',true); end if;
 v_amount:=round(coalesce((p_data->>'amount')::numeric,v_line.amount,0),2);
 if v_kind='incident' then
  v_amount:=-abs(v_amount);
  if not v_cancel and (v_amount=0 or nullif(trim(v_meta->>'occurred_at'),'') is null or (nullif(trim(v_meta->>'client_name'),'') is null and nullif(trim(v_meta->>'situation'),'') is null)) then
   raise exception 'Indica importe, fecha y hora, y la clienta o situación de la incidencia.';
  end if;
  v_inc_id:=coalesce((v_line.meta->>'incident_id')::uuid,p_line_id);
  v_date:=coalesce((v_meta->>'occurred_at')::timestamptz,v_line.created_at,now());
  v_meta:=v_meta||jsonb_build_object('incident_id',v_inc_id,'occurred_at',v_date,'invoice_id',p_invoice_id);
  insert into public.incidents(id,worker_id,month_key,title,amount,created_by,reason,kind,status,decided_by,decided_at,meta)
  values(v_inc_id,v_inv.worker_id,v_inv.month_key,v_label,abs(v_amount),p_actor_id,v_label,'manual',case when v_cancel then 'justified' else 'unjustified' end,p_actor_id,now(),v_meta)
  on conflict(id) do update set title=excluded.title,reason=excluded.reason,amount=excluded.amount,status=excluded.status,decided_by=p_actor_id,decided_at=now(),meta=excluded.meta;
  insert into public.central_notifications(business,recipient_worker_id,type,priority,title,description,action_label,action_path,state,deduplication_key,metadata,created_by)
  values('celestial',v_inv.worker_id,'invoice_incident','attention',
  case when v_cancel then 'Incidencia anulada' else 'Has recibido una multa' end,
  'Factura: '||v_inv.month_key||'. Motivo: '||v_label||'. Importe: '||abs(v_amount)||' €. Fecha y hora: '||to_char(v_date at time zone 'Europe/Madrid','DD/MM/YYYY HH24:MI')||' (Madrid). '||
  case when nullif(v_meta->>'client_name','') is not null then 'Clienta: '||(v_meta->>'client_name')||'. ' else '' end||coalesce(v_meta->>'situation',''),
  'Ver mi factura','/panel-central?tab=mi-factura','pending','invoice_incident:'||v_inc_id,
  v_meta||jsonb_build_object('amount',abs(v_amount),'cancelled',v_cancel,'month',v_inv.month_key),v_actor.user_id)
  on conflict(deduplication_key) do update set title=excluded.title,description=excluded.description,metadata=excluded.metadata,state='pending',read_at=null,resolved_at=null,updated_at=now();
 end if;
 if v_cancel then delete from public.invoice_lines where id=p_line_id and invoice_id=p_invoice_id;
 elsif p_action='add_line' then
  insert into public.invoice_lines(id,invoice_id,kind,label,amount,meta) values(p_line_id,p_invoice_id,v_kind,v_label,v_amount,v_meta);
 else update public.invoice_lines set label=v_label,amount=v_amount,meta=v_meta where id=p_line_id and invoice_id=p_invoice_id;
 end if;
 select coalesce(sum(amount),0) into v_total from public.invoice_lines where invoice_id=p_invoice_id;
 update public.invoices set total=v_total,total_calc=v_total,
 incidencias_total=(select coalesce(sum(abs(amount)),0) from public.invoice_lines where invoice_id=p_invoice_id and kind='incident'),updated_at=now()
 where id=p_invoice_id;
 return jsonb_build_object('ok',true,'total',v_total);
end $function$

CREATE OR REPLACE FUNCTION public.tarotista_bonus_save_rule(p_rule jsonb, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.tarotista_bonus_rules%rowtype; old public.tarotista_bonus_rules%rowtype;
begin
 if not exists(select 1 from public.workers where id=p_actor and role='admin' and is_active is distinct from false) then raise exception 'ADMIN_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtext('tarotista_bonus_catalog'));
 r:=jsonb_populate_record(null::public.tarotista_bonus_rules,p_rule);
 if r.id is not null then
  select * into strict old from public.tarotista_bonus_rules where id=r.id for update;
  if r.version is distinct from old.version then raise exception 'La regla ha cambiado. Recarga antes de guardar.'; end if;
 else r.id:=gen_random_uuid(); end if;
 if r.active and r.kind in ('tier','ranking') and exists(
  select 1 from public.tarotista_bonus_rules b where b.id<>r.id and b.active and b.kind=r.kind and b.metric=r.metric
   and daterange(b.start_date,b.end_date,'[]') && daterange(r.start_date,r.end_date,'[]')
   and ((r.kind='ranking' and b.position=r.position) or (r.kind='tier' and numrange(b.minimum,b.maximum,'[]') && numrange(r.minimum,r.maximum,'[]')))
 ) then raise exception 'Ya existe un tramo o posición activo que se solapa con esta regla.'; end if;
 insert into public.tarotista_bonus_rules(id,name,description,kind,metric,minimum,maximum,target,reward,position,active,start_date,end_date,periodicity,stackable,max_claims,sort_order,image_url,updated_by)
 values(r.id,r.name,r.description,r.kind,r.metric,r.minimum,r.maximum,r.target,r.reward,r.position,r.active,r.start_date,r.end_date,r.periodicity,r.stackable,r.max_claims,r.sort_order,r.image_url,p_actor)
 on conflict(id) do update set name=excluded.name,description=excluded.description,kind=excluded.kind,metric=excluded.metric,minimum=excluded.minimum,maximum=excluded.maximum,target=excluded.target,reward=excluded.reward,position=excluded.position,active=excluded.active,start_date=excluded.start_date,end_date=excluded.end_date,periodicity=excluded.periodicity,stackable=excluded.stackable,max_claims=excluded.max_claims,sort_order=excluded.sort_order,image_url=excluded.image_url,version=public.tarotista_bonus_rules.version+1,updated_at=now(),updated_by=p_actor returning * into r;
 return to_jsonb(r);
end $function$

CREATE OR REPLACE FUNCTION public.tarotista_bonus_void(p_award uuid, p_actor uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.tarotista_bonus_awards%rowtype; inv public.invoices%rowtype;
begin
 if not exists(select 1 from public.workers where id=p_actor and role='admin' and is_active is distinct from false) then raise exception 'ADMIN_REQUIRED'; end if;
 if length(trim(p_reason))<3 then raise exception 'Indica el motivo de anulación.'; end if;
 select * into strict a from public.tarotista_bonus_awards where id=p_award;
 select * into strict inv from public.invoices where id=a.invoice_id for update;
 if inv.status not in ('draft','pending','review') then raise exception 'La factura está cerrada. No se puede modificar el premio.'; end if;
 update public.tarotista_bonus_awards set status='void',voided_at=now(),voided_by=p_actor,void_reason=p_reason where id=p_award and status='included';
 delete from public.invoice_lines where invoice_id=inv.id and meta->>'bonus_award_id'=p_award::text;
 update public.invoices set total=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=inv.id),total_calc=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=inv.id),bonus_captadas=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=inv.id and kind='bonus_captadas'),bonus_ranking=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=inv.id and kind='bonus_ranking'),updated_at=now() where id=inv.id;
end $function$

CREATE OR REPLACE FUNCTION public.invoice_regenerate_preserving_manual(p_worker_id uuid, p_month text, p_lines jsonb, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_inv public.invoices%rowtype; v_line jsonb; v_inc public.incidents%rowtype; v_total numeric; v_new boolean:=false; v_candidate jsonb; v_rule public.tarotista_bonus_rules%rowtype; v_award public.tarotista_bonus_awards%rowtype; v_versions jsonb;
begin
 if p_month !~ '^\d{4}-\d{2}$' or jsonb_typeof(p_lines)<>'array' then raise exception 'INVALID_INPUT'; end if;
 insert into public.invoices(worker_id,month_key,status,total,total_calc)
 values(p_worker_id,p_month,'draft',0,0) on conflict(worker_id,month_key) do nothing;
 v_new:=found;
 select * into strict v_inv from public.invoices where worker_id=p_worker_id and month_key=p_month for update;
 if coalesce(v_inv.status,'') not in ('draft','pending','review') then return jsonb_build_object('skipped',true); end if;

 if coalesce((p_snapshot->>'bonus_engine')::boolean,false) then
  -- The existing invoice lock serializes concurrent closing, regeneration and cancellation.
  if exists(select 1 from public.invoice_lines where invoice_id=v_inv.id and kind in ('bonus_captadas','bonus_ranking','bonus_repite_goal') and not(meta ? 'bonus_award_id') and (coalesce(meta->>'source','')<>'auto_generate' or meta->>'manual_override'='true')) then
   raise exception 'Esta factura contiene bonos anteriores o editados manualmente. Revísalos antes de cerrar los nuevos bonos.';
  end if;
  if coalesce((p_snapshot->>'close_bonuses')::boolean,false) and v_inv.bonus_closed_at is null then
   if p_month>=to_char(now() at time zone 'Europe/Madrid','YYYY-MM') then raise exception 'El periodo todavía no ha terminado.'; end if;
   if not exists(select 1 from public.workers where id=(p_snapshot->>'actor_id')::uuid and role='admin' and is_active is distinct from false) then raise exception 'ADMIN_REQUIRED'; end if;
   perform pg_advisory_xact_lock(hashtext('tarotista_bonus_catalog'));
   select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) order by id),'[]') into v_versions from public.tarotista_bonus_rules;
   if v_versions is distinct from p_snapshot->'bonus_versions' then raise exception 'La configuración ha cambiado. Actualiza y vuelve a cerrar.'; end if;
   for v_candidate in select value from jsonb_array_elements(coalesce(p_snapshot->'bonus_candidates','[]')) loop
    select * into strict v_rule from public.tarotista_bonus_rules where id=(v_candidate->>'rule_id')::uuid;
    if not v_rule.active or v_rule.start_date>(p_month||'-01')::date+interval '1 month'-interval '1 day' or (v_rule.end_date is not null and v_rule.end_date<(p_month||'-01')::date) then raise exception 'Regla fuera de periodo.'; end if;
    if (v_candidate->>'units')::numeric<=0 or (v_rule.kind<>'tier' and (v_candidate->>'units')::numeric>v_rule.max_claims) then raise exception 'Cantidad de premios no válida.'; end if;
    if (v_rule.periodicity='monthly' and v_candidate->>'period_key'<>p_month) or (v_rule.periodicity='once' and v_candidate->>'period_key'<>'once:'||v_rule.start_date::text||':'||v_rule.end_date::text) then raise exception 'Referencia de periodo no válida.'; end if;
    insert into public.tarotista_bonus_awards(worker_id,rule_id,period_key,invoice_month,amount,units,rule_snapshot,metrics_snapshot,reason,invoice_id,confirmed_by)
    values(p_worker_id,v_rule.id,v_candidate->>'period_key',p_month,round((v_candidate->>'units')::numeric*v_rule.reward,2),(v_candidate->>'units')::numeric,to_jsonb(v_rule),v_candidate,v_rule.name,v_inv.id,(p_snapshot->>'actor_id')::uuid)
    on conflict(worker_id,rule_id,period_key) do nothing;
   end loop;
   update public.invoices set bonus_closed_at=now(),bonus_rules_snapshot=p_snapshot->'bonus_versions' where id=v_inv.id;
  end if;
 end if;
 -- Solo se sustituyen conceptos automáticos. Ajustes y bonus manuales conservan ID.
 delete from public.invoice_lines where invoice_id=v_inv.id
 and meta->>'source' in ('auto_generate','fixed_salary');
 for v_line in select value from jsonb_array_elements(p_lines) loop
  if (v_inv.bonus_closed_at is not null or coalesce((p_snapshot->>'bonus_engine')::boolean,false)) and v_line->>'kind' in ('bonus_captadas','bonus_ranking','bonus_repite_goal','bonus_challenge') then continue; end if;
  if exists(select 1 from public.invoice_lines where invoice_id=v_inv.id and kind=v_line->>'kind' and meta->>'manual_override'='true') then continue; end if;
  if v_line->>'kind'='salary_bonus' and exists(select 1 from public.invoice_lines where invoice_id=v_inv.id and kind='salary_bonus') then continue; end if;
  insert into public.invoice_lines(invoice_id,kind,label,amount,meta)
  values(v_inv.id,v_line->>'kind',v_line->>'label',(v_line->>'amount')::numeric,v_line->'meta');
 end loop;
 -- Las incidencias guardadas son la fuente; una decisión justificada deja de descontar.
 delete from public.invoice_lines l where l.invoice_id=v_inv.id and l.meta ? 'incident_id'
 and exists(select 1 from public.incidents i where i.id::text=l.meta->>'incident_id' and coalesce(i.status,'unjustified')<>'unjustified');
 for v_inc in select * from public.incidents where worker_id=p_worker_id and month_key=p_month and coalesce(status,'unjustified')='unjustified' loop
  update public.invoice_lines set amount=-abs(v_inc.amount),label=v_inc.title
   where invoice_id=v_inv.id and meta->>'incident_id'=v_inc.id::text;
  if not found then
   insert into public.invoice_lines(invoice_id,kind,label,amount,meta)
   values(v_inv.id,'incident',v_inc.title,-abs(v_inc.amount),coalesce(v_inc.meta,'{}')||jsonb_build_object('incident_id',v_inc.id,'source','incident_record'));
  end if;
 end loop;

 -- Confirmed rewards are restored by their own stable reference, never recalculated from new rules.
 for v_award in select * from public.tarotista_bonus_awards where invoice_id=v_inv.id and status='included' loop
  insert into public.invoice_lines(invoice_id,kind,label,amount,meta)
  values(v_inv.id,case v_award.rule_snapshot->>'kind' when 'tier' then 'bonus_captadas' when 'ranking' then 'bonus_ranking' else 'bonus_challenge' end,v_award.reason,v_award.amount,
   jsonb_build_object('source','bonus_award','bonus_award_id',v_award.id,'rule_id',v_award.rule_id,'period',v_award.period_key,'locked',true,'protected',true))
  on conflict(invoice_id,(meta->>'bonus_award_id')) where meta ? 'bonus_award_id' do nothing;
 end loop;
 select coalesce(sum(amount),0) into v_total from public.invoice_lines where invoice_id=v_inv.id;
 update public.invoices set total=v_total,total_calc=v_total,
 incidencias_total=(select coalesce(sum(abs(amount)),0) from public.invoice_lines where invoice_id=v_inv.id and kind='incident'),
 minutes_total=coalesce((p_snapshot->>'minutes_total')::numeric,0),pay_minutes=coalesce((p_snapshot->>'pay_minutes')::numeric,0),
 captadas_total=coalesce((p_snapshot->>'captadas_total')::integer,0),bonus_captadas=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=v_inv.id and kind='bonus_captadas'),bonus_ranking=(select coalesce(sum(amount),0) from public.invoice_lines where invoice_id=v_inv.id and kind='bonus_ranking'),
 salary_base=coalesce((p_snapshot->>'salary_base')::numeric,0),updated_at=now() where id=v_inv.id;
 return jsonb_build_object('id',v_inv.id,'created',v_new,'total',v_total,'line_count',(select count(*) from public.invoice_lines where invoice_id=v_inv.id));
end $function$

CREATE OR REPLACE FUNCTION public.tc_central_statistics_update(p_actor uuid, p_worker uuid, p_action text, p_payload jsonb, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare prior central_statistics_operations; result jsonb; cfg central_work_config_versions; at_time timestamptz:=clock_timestamp();
 today date:=(clock_timestamp() at time zone 'America/Guayaquil')::date; month_start date; day date; requested date[]; existing date[]; delta integer;
begin
 if not exists(select 1 from workers where id=p_actor and role='admin' and is_active=true) then raise exception 'FORBIDDEN'; end if;
 if not exists(select 1 from workers where id=p_worker and role in ('central','admin') and is_active=true) then raise exception 'WORKER_NOT_FOUND'; end if;
 if p_operation is null or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'INVALID_PAYLOAD'; end if;
 perform pg_advisory_xact_lock(hashtextextended('central-statistics:'||p_worker::text,0));
 select * into prior from central_statistics_operations where id=p_operation;
 if found then
  if prior.worker_id<>p_worker or prior.actor_id<>p_actor or prior.action<>p_action or prior.payload<>p_payload then raise exception 'OPERATION_CONFLICT'; end if;
  return prior.result||jsonb_build_object('duplicate_prevented',true);
 end if;
 if p_action='settings' then
  if not (p_payload ?& array['monthly_salary_eur','overtime_hourly_rate_eur','weekday_start','weekday_end','weekend_start','weekend_end']) then raise exception 'INVALID_SETTINGS'; end if;
  if (p_payload->>'monthly_salary_eur')::numeric<0 or (p_payload->>'monthly_salary_eur')::numeric>100000
     or (p_payload->>'overtime_hourly_rate_eur')::numeric<0 or (p_payload->>'overtime_hourly_rate_eur')::numeric>10000 then raise exception 'INVALID_RATE'; end if;
  insert into central_work_config_versions(worker_id,effective_from,monthly_salary_eur,overtime_hourly_rate_eur,weekday_start,weekday_end,weekend_start,weekend_end,created_by,reason)
  values(p_worker,at_time,(p_payload->>'monthly_salary_eur')::numeric,(p_payload->>'overtime_hourly_rate_eur')::numeric,
   nullif(p_payload->>'weekday_start','')::time,nullif(p_payload->>'weekday_end','')::time,
   (p_payload->>'weekend_start')::time,(p_payload->>'weekend_end')::time,p_actor,'Cambio administrativo; válido desde este instante.') returning * into cfg;
  result:=jsonb_build_object('ok',true,'version_id',cfg.id,'effective_from',cfg.effective_from);
 elsif p_action='weekends' then
  if coalesce(p_payload->>'month','') !~ '^\d{4}-(0[1-9]|1[0-2])$' or jsonb_typeof(p_payload->'days')<>'array' or jsonb_array_length(p_payload->'days')>10 then raise exception 'INVALID_WEEKENDS'; end if;
  month_start:=((p_payload->>'month')||'-01')::date;
  if month_start<date_trunc('month',today)::date or month_start>today+interval '1 year' then raise exception 'INVALID_MONTH'; end if;
  select coalesce(array_agg(distinct value::date),'{}'::date[]) into requested from jsonb_array_elements_text(p_payload->'days');
  if exists(select 1 from unnest(requested) d where d<=today or date_trunc('month',d)::date<>month_start or extract(isodow from d) not in (6,7)) then raise exception 'ONLY_FUTURE_WEEKEND_DATES'; end if;
  select * into cfg from central_work_config_versions where worker_id=p_worker order by effective_from desc,id desc limit 1;
  if not found then raise exception 'CONFIG_REQUIRED'; end if;
  -- Consider adjacent months too; Saturday and Sunday can straddle a boundary.
  if exists(with latest as(select distinct on(work_date) work_date,is_working from central_workday_overrides where worker_id=p_worker order by work_date,created_at desc,id desc),
   chosen as(select unnest(requested) d union select work_date from latest where is_working and (date_trunc('month',work_date)::date<>month_start or work_date<=today) and extract(isodow from work_date) in (6,7))
   select 1 from chosen group by date_trunc('week',d) having count(*)>1) then raise exception 'ONE_WEEKEND_DAY_PER_WEEK'; end if;
  select coalesce(array_agg(work_date),'{}'::date[]) into existing from (select distinct on(work_date) work_date,is_working from central_workday_overrides where worker_id=p_worker and work_date>today and date_trunc('month',work_date)::date=month_start order by work_date,created_at desc,id desc) x where is_working;
  foreach day in array existing loop
   if not(day=any(requested)) then insert into central_workday_overrides(worker_id,work_date,is_working,created_by) values(p_worker,day,false,p_actor); end if;
  end loop;
  foreach day in array requested loop
   insert into central_workday_overrides(worker_id,work_date,is_working,start_time,end_time,created_by) values(p_worker,day,true,cfg.weekend_start,cfg.weekend_end,p_actor);
  end loop;
  result:=jsonb_build_object('ok',true,'days',to_jsonb(requested));
 elsif p_action='adjustment' then
  if coalesce(p_payload->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'INVALID_DATE'; end if;
  day:=(p_payload->>'date')::date;delta:=(p_payload->>'minutes')::integer;
  if day>today or day<(select (activated_at at time zone 'America/Guayaquil')::date from central_statistics_activation where singleton)
     then raise exception 'OUTSIDE_RECORDED_PERIOD'; end if;
  if delta=0 or abs(delta)>1440 or p_payload->>'category' not in ('ordinary','outside_schedule') or length(btrim(coalesce(p_payload->>'reason',''))) not between 5 and 2000 then raise exception 'INVALID_ADJUSTMENT'; end if;
  if coalesce((select sum(minutes) from central_time_adjustments where worker_id=p_worker and work_date=day and category=p_payload->>'category'),0)
     <>coalesce((p_payload->>'expected_category_adjustment')::integer,0) then raise exception 'ADJUSTMENT_CHANGED'; end if;
  if coalesce((select sum(minutes) from central_time_adjustments where worker_id=p_worker and work_date=day),0)
     <>coalesce((p_payload->>'expected_total_adjustment')::integer,0) then raise exception 'ADJUSTMENT_CHANGED'; end if;
  if coalesce((p_payload->>'category_recorded_minutes')::numeric,0)+delta<0 then raise exception 'NEGATIVE_RECORDED_HOURS'; end if;
  if coalesce((p_payload->>'total_recorded_minutes')::numeric,0)+delta>1440 then raise exception 'INVALID_DAILY_HOURS'; end if;
  select * into cfg from central_work_config_versions where worker_id=p_worker and effective_from<least(at_time,(day+1)::timestamp at time zone 'America/Guayaquil') order by effective_from desc,id desc limit 1;
  insert into central_time_adjustments(id,worker_id,work_date,minutes,category,reason,created_by,hourly_rate_eur)
   values(p_operation,p_worker,day,delta,p_payload->>'category',btrim(p_payload->>'reason'),p_actor,cfg.overtime_hourly_rate_eur);
  result:=jsonb_build_object('ok',true,'adjustment_id',p_operation);
 else raise exception 'UNKNOWN_ACTION'; end if;
 insert into central_statistics_operations(id,worker_id,actor_id,action,payload,result) values(p_operation,p_worker,p_actor,p_action,p_payload,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.staff_chat_mark_read(p_worker_id uuid, p_thread_id uuid, p_through_message_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_message_at timestamptz;
  v_read_at timestamptz;
begin
  select w.role into v_role from public.workers w
    where w.id=p_worker_id and w.is_active and w.role in ('admin','central','tarotista') for share;
  if not found then raise exception 'FORBIDDEN'; end if;
  perform 1 from public.chat_threads t where t.id=p_thread_id
    and (v_role='admin' or p_worker_id=t.central_worker_id or p_worker_id=t.tarotist_worker_id) for share;
  if not found then raise exception 'FORBIDDEN'; end if;
  select m.created_at into v_message_at from public.chat_messages m
    where m.id=p_through_message_id and m.thread_id=p_thread_id;
  if not found then raise exception 'MESSAGE_NOT_FOUND'; end if;
  if v_message_at>clock_timestamp() then raise exception 'INVALID_MESSAGE_TIMESTAMP'; end if;
  insert into public.chat_thread_reads as r(thread_id,worker_id,last_read_at,updated_at)
    values(p_thread_id,p_worker_id,v_message_at,clock_timestamp())
    on conflict on constraint chat_thread_reads_pkey do update
      set last_read_at=greatest(r.last_read_at,excluded.last_read_at),
        updated_at=case when excluded.last_read_at>r.last_read_at then excluded.updated_at else r.updated_at end
    returning last_read_at into v_read_at;
  return v_read_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.staff_chat_send_media_message(p_worker_id uuid, p_thread_id uuid, p_client_message_id text, p_body text, p_attachment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w public.workers%rowtype; t public.chat_threads%rowtype;
 a public.staff_chat_attachments%rowtype; m public.chat_messages%rowtype;
 saved_attachment uuid; duplicate boolean:=false;
begin
 select * into w from public.workers where id=p_worker_id and is_active is true and role in ('central','tarotista','admin');
 if w.id is null then raise exception 'FORBIDDEN'; end if;
 select * into t from public.chat_threads where id=p_thread_id;
 if t.id is null then raise exception 'THREAD_NOT_FOUND'; end if;
 if w.role<>'admin' and w.id is distinct from t.central_worker_id and w.id is distinct from t.tarotist_worker_id then raise exception 'FORBIDDEN'; end if;
 if p_attachment_id is null or length(btrim(coalesce(p_client_message_id,''))) not between 1 and 128
    or length(btrim(coalesce(p_body,''))) not between 1 and 2000 then raise exception 'INVALID_MESSAGE'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_worker_id::text||':'||p_client_message_id,0));
 select * into m from public.chat_messages where sender_worker_id=p_worker_id and client_message_id=p_client_message_id;
 if found then
  select id into saved_attachment from public.staff_chat_attachments where message_id=m.id;
  if m.thread_id<>p_thread_id or m.body<>p_body or saved_attachment is distinct from p_attachment_id then raise exception 'MESSAGE_ID_CONFLICT'; end if;
  duplicate:=true;
 else
  select * into a from public.staff_chat_attachments where id=p_attachment_id for update;
  if a.id is null then raise exception 'ATTACHMENT_NOT_FOUND'; end if;
  if a.sender_worker_id<>p_worker_id or a.thread_id<>p_thread_id then raise exception 'FORBIDDEN'; end if;
  if a.message_id is not null then raise exception 'ATTACHMENT_ALREADY_USED'; end if;
  if a.validated_at is null then raise exception 'ATTACHMENT_NOT_UPLOADED'; end if;
  insert into public.chat_messages(thread_id,sender_worker_id,sender_display_name,body,client_message_id)
   values(p_thread_id,p_worker_id,w.display_name,p_body,p_client_message_id) returning * into m;
  update public.staff_chat_attachments set message_id=m.id where id=a.id;
  update public.chat_threads set last_message_at=m.created_at,last_message_preview=left(m.body,180),status='open'
   where id=p_thread_id and (last_message_at is null or last_message_at<=m.created_at);
 end if;
 return jsonb_build_object('message',to_jsonb(m),'duplicate',duplicate);
end $function$

CREATE OR REPLACE FUNCTION public.tc_save_roulette_config(p_actor uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare action text:=p_data->>'action'; cid uuid:=nullif(p_data->>'campaign_id','')::uuid;
 rid uuid:=nullif(p_data->>'id','')::uuid; before_row jsonb; after_row jsonb; n integer; lvl smallint;
 total numeric; items jsonb:=p_data->'probabilities';
begin
 if not exists(select 1 from workers where user_id=p_actor and role='admin' and is_active is distinct from false) then raise exception 'ADMIN_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtext('tc_roulette_config'));
 if action='create_campaign' then
   insert into tc_client_roulette_campaigns(name,title,subtitle,status,active_until_disabled,created_by,updated_at)
   values(coalesce(nullif(p_data->>'name',''),'Nueva Ruleta'),coalesce(nullif(p_data->>'title',''),'Ruleta Celestial'),p_data->>'subtitle','draft',true,p_actor,now())
   returning id,to_jsonb(tc_client_roulette_campaigns.*) into cid,after_row;
 elsif action in ('save_campaign','activate_campaign') then
   cid:=rid; select to_jsonb(c) into before_row from tc_client_roulette_campaigns c where id=cid for update;
   if before_row is null then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
   if action='activate_campaign' then
     update tc_client_roulette_campaigns set status='inactive',updated_at=now() where status='active' and id<>cid;
     update tc_client_roulette_campaigns set status='active',starts_at=now(),ends_at=null,active_until_disabled=true,updated_at=now() where id=cid returning to_jsonb(tc_client_roulette_campaigns.*) into after_row;
   else
     if nullif(btrim(p_data->>'name'),'') is null or nullif(btrim(p_data->>'title'),'') is null or p_data->>'status' not in ('draft','scheduled','active','inactive','finished','archived') then raise exception 'INVALID_CAMPAIGN'; end if;
     if nullif(p_data->>'ends_at','')::timestamptz<=nullif(p_data->>'starts_at','')::timestamptz then raise exception 'INVALID_DATES'; end if;
     if p_data->>'status'='active' then update tc_client_roulette_campaigns set status='inactive',updated_at=now() where status='active' and id<>cid; end if;
     update tc_client_roulette_campaigns set name=left(p_data->>'name',120),title=left(p_data->>'title',160),subtitle=left(p_data->>'subtitle',300),
      status=p_data->>'status',starts_at=nullif(p_data->>'starts_at','')::timestamptz,
      ends_at=case when (p_data->>'active_until_disabled')::boolean then null else nullif(p_data->>'ends_at','')::timestamptz end,
      active_until_disabled=(p_data->>'active_until_disabled')::boolean,diamond_enabled=(p_data->>'diamond_enabled')::boolean,
      diamond_rank=p_data->>'diamond_rank',updated_at=now() where id=cid returning to_jsonb(tc_client_roulette_campaigns.*) into after_row;
   end if;
 elsif action='save_reward' then
   lvl:=(p_data->>'nivel')::smallint;
   if cid is null or lvl not between 1 and 5 or nullif(btrim(p_data->>'name'),'') is null
      or p_data->>'reward_type' not in ('minutes','coins','oracle_credits','rank','ritual','streak_minutes','perk')
      or p_data->>'rarity' not in ('common','uncommon','rare','epic','legendary','ultra','diamond','jackpot')
      or p_data->>'fulfillment_mode' not in ('immediate','temporary','manual','claim','scheduled')
      or (p_data->>'weight')::numeric<0 or (p_data->>'reward_value')::numeric<0 then raise exception 'INVALID_REWARD'; end if;
   if p_data->>'reward_type' in ('coins','minutes','oracle_credits') and ((p_data->>'reward_value')::numeric<>trunc((p_data->>'reward_value')::numeric) or (p_data->>'reward_value')::numeric<1) then raise exception 'REWARD_VALUE_MUST_BE_POSITIVE_INTEGER'; end if;
   if rid is not null then select to_jsonb(r) into before_row from tc_client_roulette_rewards r where id=rid for update; end if;
   rid:=coalesce(rid,gen_random_uuid());
   insert into tc_client_roulette_rewards(id,campaign_id,nivel,name,description,reward_type,reward_value,rarity,weight,special,fulfillment_mode,icon_key,metadata,is_active,sort_order,updated_at)
   values(rid,cid,lvl,left(p_data->>'name',140),left(p_data->>'description',500),p_data->>'reward_type',(p_data->>'reward_value')::numeric,
      p_data->>'rarity',(p_data->>'weight')::numeric,coalesce((p_data->>'special')::boolean,false),p_data->>'fulfillment_mode',left(p_data->>'icon_key',50),
      coalesce(p_data->'metadata','{}'),coalesce((p_data->>'is_active')::boolean,true),coalesce((p_data->>'sort_order')::integer,0),now())
   on conflict(id) do update set campaign_id=excluded.campaign_id,nivel=excluded.nivel,name=excluded.name,description=excluded.description,
      reward_type=excluded.reward_type,reward_value=excluded.reward_value,rarity=excluded.rarity,weight=excluded.weight,special=excluded.special,
      fulfillment_mode=excluded.fulfillment_mode,icon_key=excluded.icon_key,metadata=excluded.metadata,is_active=excluded.is_active,sort_order=excluded.sort_order,updated_at=now()
   returning to_jsonb(tc_client_roulette_rewards.*) into after_row;
 elsif action='save_probabilities' then
   lvl:=(p_data->>'nivel')::smallint;
   if cid is null or lvl not between 1 and 5 or jsonb_typeof(items)<>'array' then raise exception 'INVALID_PROBABILITIES'; end if;
   select count(*),sum((x->>'probability')::numeric) into n,total from jsonb_array_elements(items) x;
   if n=0 or abs(total-100)>0.00001 or exists(select 1 from jsonb_array_elements(items) x where (x->>'probability')::numeric<0 or (x->>'probability')::numeric>100)
     or n<>(select count(distinct x->>'id') from jsonb_array_elements(items) x)
     or n<>(select count(*) from tc_client_roulette_rewards where campaign_id=cid and nivel=lvl and is_active)
     or n<>(select count(*) from tc_client_roulette_rewards r join jsonb_array_elements(items) x on r.id=(x->>'id')::uuid where r.campaign_id=cid and r.nivel=lvl and r.is_active) then raise exception 'PROBABILITIES_MUST_COVER_ALL_ACTIVE_REWARDS_AND_SUM_100'; end if;
   select jsonb_agg(to_jsonb(r)) into before_row from tc_client_roulette_rewards r where campaign_id=cid and nivel=lvl;
   update tc_client_roulette_rewards r set weight=(x->>'probability')::numeric,updated_at=now() from jsonb_array_elements(items) x where r.id=(x->>'id')::uuid;
   after_row:=jsonb_build_object('nivel',lvl,'probabilities',items);
 elsif action in ('toggle_reward','delete_reward') then
   select to_jsonb(r),campaign_id into before_row,cid from tc_client_roulette_rewards r where id=rid for update;
   if before_row is null then raise exception 'REWARD_NOT_FOUND'; end if;
   if action='toggle_reward' then update tc_client_roulette_rewards set is_active=(p_data->>'is_active')::boolean,updated_at=now() where id=rid returning to_jsonb(tc_client_roulette_rewards.*) into after_row;
   elsif exists(select 1 from cliente_ruleta_giros where reward_id=rid::text) then update tc_client_roulette_rewards set is_active=false,updated_at=now() where id=rid returning to_jsonb(tc_client_roulette_rewards.*) into after_row;
   else delete from tc_client_roulette_rewards where id=rid; end if;
 elsif action='complete_entitlement' then
   select to_jsonb(e),campaign_id into before_row,cid from tc_client_roulette_entitlements e where id=rid for update;
   if before_row is null then raise exception 'BENEFIT_NOT_FOUND'; end if;
   update tc_client_roulette_entitlements set status='completed',updated_at=now() where id=rid returning to_jsonb(tc_client_roulette_entitlements.*) into after_row;
 else raise exception 'INVALID_ACTION'; end if;
 insert into tc_client_roulette_audit(campaign_id,reward_id,actor_user_id,action,snapshot)
 values(cid,case when action in ('save_reward','toggle_reward') then rid end,p_actor,action,jsonb_build_object('before',before_row,'after',after_row));
 insert into tc_client_benefit_audit(actor_user_id,action,entity,entity_id,before_data,after_data)
 values(p_actor,action,'roulette_config',coalesce(rid,cid)::text,before_row,after_row);
end $function$

CREATE OR REPLACE FUNCTION public.tc_save_rank_benefit_config(p_actor uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.tc_client_rank_benefits%rowtype; b public.tc_client_purchase_bands%rowtype; promo public.tc_client_promotions%rowtype;
  v_id uuid; before_row jsonb; after_row jsonb; rev integer;
begin
  if not exists(select 1 from public.workers where user_id=p_actor and role='admin' and is_active is distinct from false) then raise exception 'ADMIN_REQUIRED'; end if;
  perform set_config('tc.benefit_actor',p_actor::text,true);
  if p_action='rank' then
    select * into r from public.tc_client_rank_benefits where rank_key=p_data->>'rank_key' for update;
    if r.rank_key is not null and r.revision<>coalesce((p_data->>'revision')::integer,0) then raise exception 'CONFIG_CONFLICT'; end if;
    insert into public.tc_client_rank_benefits(rank_key,label,min_spend,sort_order,is_active,coins_enabled,purchase_coins,roulette_enabled,roulette_level,roulette_spins,daily_bonus_enabled,revision,updated_by)
    values(p_data->>'rank_key',p_data->>'label',(p_data->>'min_spend')::numeric,coalesce((p_data->>'sort_order')::integer,0),
      (p_data->>'is_active')::boolean,(p_data->>'coins_enabled')::boolean,(p_data->>'purchase_coins')::integer,
      (p_data->>'roulette_enabled')::boolean,(p_data->>'roulette_level')::smallint,(p_data->>'roulette_spins')::integer,
      (p_data->>'daily_bonus_enabled')::boolean,coalesce(r.revision,0)+1,p_actor)
    on conflict(rank_key) do update set label=excluded.label,min_spend=excluded.min_spend,sort_order=excluded.sort_order,is_active=excluded.is_active,
      coins_enabled=excluded.coins_enabled,purchase_coins=excluded.purchase_coins,roulette_enabled=excluded.roulette_enabled,
      roulette_level=excluded.roulette_level,roulette_spins=excluded.roulette_spins,daily_bonus_enabled=excluded.daily_bonus_enabled,
      revision=excluded.revision,updated_by=p_actor,updated_at=now() returning to_jsonb(tc_client_rank_benefits.*) into after_row;
  elsif p_action='band' then
    perform pg_advisory_xact_lock(hashtext('tc_purchase_bands'));
    v_id:=coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());
    select * into b from public.tc_client_purchase_bands where tc_client_purchase_bands.id=v_id for update;
    if b.id is not null and b.revision<>coalesce((p_data->>'revision')::integer,0) then raise exception 'CONFIG_CONFLICT'; end if;
    insert into public.tc_client_purchase_bands(id,currency,min_amount,max_amount,roulette_level,spins,is_active,revision,updated_by)
    values(v_id,p_data->>'currency',(p_data->>'min_amount')::numeric,nullif(p_data->>'max_amount','')::numeric,(p_data->>'roulette_level')::smallint,
      (p_data->>'spins')::integer,(p_data->>'is_active')::boolean,coalesce(b.revision,0)+1,p_actor)
    on conflict(id) do update set currency=excluded.currency,min_amount=excluded.min_amount,max_amount=excluded.max_amount,
      roulette_level=excluded.roulette_level,spins=excluded.spins,is_active=excluded.is_active,revision=excluded.revision,updated_by=p_actor,updated_at=now()
    returning to_jsonb(tc_client_purchase_bands.*) into after_row;
  elsif p_action='bonus' then
    v_id:=coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());
    select * into promo from public.tc_client_promotions where tc_client_promotions.id=v_id for update;
    if promo.id is not null and (promo.promotion_kind<>'rank_bonus' or promo.benefit_revision<>coalesce((p_data->>'benefit_revision')::integer,0)) then raise exception 'CONFIG_CONFLICT'; end if;
    if p_data->>'status' not in ('active','inactive','draft','scheduled') then raise exception 'INVALID_STATUS'; end if;
    if (p_data->>'ends_at')::timestamptz<=(p_data->>'starts_at')::timestamptz then raise exception 'INVALID_DATES'; end if;
    if coalesce((p_data->'benefit'->>'coins')::integer,0)<0 or coalesce((p_data->'benefit'->>'minutes')::integer,0)<0 or coalesce((p_data->'benefit'->>'oracle_credits')::integer,0)<0
      or coalesce((p_data->'benefit'->>'coins')::integer,0)+coalesce((p_data->'benefit'->>'minutes')::integer,0)+coalesce((p_data->'benefit'->>'oracle_credits')::integer,0)<=0 then raise exception 'BONUS_INVALID'; end if;
    before_row:=case when promo.id is not null then to_jsonb(promo) end;
    insert into public.tc_client_promotions(id,name,description,status,starts_at,ends_at,active_until_disabled,promotion_kind,authorized_rank,image_url,benefit,max_uses_per_client,benefit_revision,created_by,updated_at)
    values(v_id,p_data->>'name',p_data->>'description',p_data->>'status',nullif(p_data->>'starts_at','')::timestamptz,nullif(p_data->>'ends_at','')::timestamptz,
      coalesce((p_data->>'active_until_disabled')::boolean,false),'rank_bonus',p_data->>'authorized_rank',nullif(p_data->>'image_url',''),
      p_data->'benefit',coalesce((p_data->>'max_uses_per_client')::integer,1),coalesce(promo.benefit_revision,0)+1,p_actor,now())
    on conflict(id) do update set name=excluded.name,description=excluded.description,status=excluded.status,starts_at=excluded.starts_at,ends_at=excluded.ends_at,
      active_until_disabled=excluded.active_until_disabled,authorized_rank=excluded.authorized_rank,image_url=excluded.image_url,
      benefit=excluded.benefit,max_uses_per_client=excluded.max_uses_per_client,benefit_revision=excluded.benefit_revision,updated_at=now()
    returning to_jsonb(tc_client_promotions.*) into after_row;
    insert into public.tc_client_benefit_audit(actor_user_id,action,entity,entity_id,before_data,after_data)
      values(p_actor,'bonus_saved','tc_client_promotions',v_id::text,before_row,after_row);
    insert into public.tc_client_promotion_audit(promotion_id,action,actor_user_id,snapshot) values(v_id,'rank_bonus_saved',p_actor,after_row);
  else raise exception 'INVALID_ACTION'; end if;
  return after_row;
end $function$

CREATE OR REPLACE FUNCTION public.tc_save_benefit_rule(p_rule jsonb, p_actor uuid, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.client_benefit_rules%rowtype; old_r public.client_benefit_rules%rowtype; v_id uuid;
begin
 if not exists(select 1 from public.workers where id=p_actor and lower(role) in ('admin','ceo','supervisor') and coalesce(is_active,true)) then raise exception 'FORBIDDEN'; end if;
 perform pg_catalog.pg_advisory_xact_lock(872191);
 v_id := coalesce(nullif(p_rule->>'id','')::uuid,gen_random_uuid());
 select * into old_r from public.client_benefit_rules where id=v_id for update;
 if old_r.id is not null and old_r.revision is distinct from p_expected_revision then raise exception 'RULE_CHANGED_RELOAD'; end if;
 select * into r from jsonb_populate_record(null::public.client_benefit_rules,
   jsonb_build_object('id',v_id,'name','','description','','event','purchase','claim_mode','automatic','scope','regular','currency','EUR','min_amount',0,'mode','add','priority',0,'sort_order',0,'active',false,'starts_at',now()) || p_rule);
 r.id:=v_id; r.revision:=coalesce(old_r.revision,0)+1; r.created_at:=coalesce(old_r.created_at,now()); r.updated_at:=now();
 if r.active and r.archived_at is null and r.event='purchase' and exists(
  select 1 from public.client_benefit_rules b where b.id<>r.id and b.active and b.archived_at is null and b.event='purchase'
   and b.currency=r.currency and (b.rank is null or r.rank is null or b.rank=r.rank) and b.priority=r.priority
   and (b.scope=r.scope or b.scope='all' or r.scope='all')
   and numrange(b.min_amount,b.max_amount,'(]') && numrange(r.min_amount,r.max_amount,'(]')
   and tstzrange(b.starts_at,b.ends_at,'[)') && tstzrange(r.starts_at,r.ends_at,'[)')
 ) then raise exception 'OVERLAPPING_RULE_SET_DISTINCT_PRIORITY'; end if;
 insert into public.client_benefit_rules select r.* on conflict(id) do update set
 name=excluded.name,description=excluded.description,rank=excluded.rank,event=excluded.event,claim_mode=excluded.claim_mode,
 scope=excluded.scope,currency=excluded.currency,min_amount=excluded.min_amount,max_amount=excluded.max_amount,mode=excluded.mode,
 coins=excluded.coins,coins_rate=excluded.coins_rate,free_minutes=excluded.free_minutes,oracle_credits=excluded.oracle_credits,
 roulette_spins=excluded.roulette_spins,roulette_level=excluded.roulette_level,priority=excluded.priority,sort_order=excluded.sort_order,
 active=excluded.active,starts_at=excluded.starts_at,ends_at=excluded.ends_at,archived_at=excluded.archived_at,revision=excluded.revision,updated_at=excluded.updated_at;
 insert into public.client_benefit_rule_audit(rule_id,actor_id,before_value,after_value) values(v_id,p_actor,case when old_r.id is null then null else to_jsonb(old_r) end,to_jsonb(r));
 return to_jsonb(r);
end $function$

CREATE OR REPLACE FUNCTION public.tc_recovery_act(p_user uuid, p_client uuid, p_action text, p_version integer, p_payment uuid DEFAULT NULL::uuid, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare actor workers; r crm_client_recovery; payment crm_cliente_pagos; next_status text; client_name text;
begin
 select * into actor from workers where user_id=p_user and role in ('central','admin') and is_active is distinct from false order by case when role='central' then 0 else 1 end,id limit 1;
 if actor.id is null then raise exception 'FORBIDDEN'; end if;
 if p_action not in ('contacted','no_response','recycled','recovered','restore') then raise exception 'INVALID_ACTION'; end if;
 select nombre into client_name from tc_recovery_candidates where id=p_client and eligible;
 if not found then raise exception 'NOT_ELIGIBLE'; end if;
 insert into crm_client_recovery(client_id) values(p_client) on conflict do nothing;
 select * into r from crm_client_recovery where client_id=p_client for update;
 if r.status='recovered' then return jsonb_build_object('status','recovered','already_recovered',true,'xp',75); end if;
 if r.version<>p_version then raise exception 'STALE_VERSION'; end if;
 if r.responsible_id is not null and r.responsible_id<>actor.id and actor.role<>'admin' and p_action not in ('recovered') then raise exception 'OTHER_OWNER'; end if;
 if r.status='recycled' and p_action not in ('restore','recovered') then raise exception 'RESTORE_FIRST'; end if;
 if p_action='restore' and r.status<>'recycled' then raise exception 'INVALID_ACTION'; end if;
 next_status:=case when p_action='restore' then case when r.contacted_at is null then 'pending' else 'contacted' end else p_action end;
 if p_action in ('contacted','no_response') then
  r.contacted_at:=coalesce(r.contacted_at,now()); r.responsible_id:=coalesce(r.responsible_id,actor.id);
 end if;
 if p_action='recovered' then
  if r.contacted_at is null or r.responsible_id is null then raise exception 'CONTACT_FIRST'; end if;
  select * into payment from crm_cliente_pagos where id=p_payment and cliente_id=p_client and estado='completed' and importe>0 and created_at>=r.contacted_at and created_at<=now() for update;
  if not found then raise exception 'PAYMENT_REQUIRED'; end if;
  insert into worker_xp_events(worker_id,action_key,xp_amount,reference_id,reference_label,origin,status,metadata,created_by_worker_id)
  values(r.responsible_id,'client_recovery',75,'client_recovery:'||p_client,'Cliente recuperado: '||client_name,'client_recovery','applied',jsonb_build_object('client_id',p_client,'payment_id',p_payment,'confirmed_by',actor.id),actor.id);
 end if;
 update crm_client_recovery set status=next_status,responsible_id=r.responsible_id,contacted_at=r.contacted_at,
 updated_at=now(),version=version+1,recovered_at=case when p_action='recovered' then now() else recovered_at end,
 payment_id=case when p_action='recovered' then p_payment else payment_id end,
 purchase_amount=case when p_action='recovered' then payment.importe else purchase_amount end,
 xp=case when p_action='recovered' then 75 else xp end where client_id=p_client;
 insert into crm_client_recovery_history(client_id,actor_id,status,note) values(p_client,actor.id,next_status,nullif(left(trim(p_note),1000),''));
 return jsonb_build_object('status',next_status,'xp',case when p_action='recovered' then 75 else 0 end);
end $function$
